/*

Hi all!

I still consider myself a somewhat beginner(maybe a little better) so in case I misstated something I warned you.

I wanted to continue my dive into Voronoi and also start learning more about ray marching.
I combined the 2 into this project

I took insight and/or copied code from the following sources:
  https://blog.maximeheckel.com/posts/painting-with-math-a-gentle-study-of-raymarching/
  https://inspirnathan.com/posts/52-shadertoy-tutorial-part-6 plus other sections   
  And as always a big shout out to Inigo Quilez for all of his articles. Especially the smin() function!

I have 2 scenes that flip every 10 seconds (const TIME_INTERVAL)
Both scenes involve ray marching but produce different results.

1. Ray marching - a scene that shows ray marching paths.

2. Voronoi - this one has several levels. The small moving spheres should be the actual Voronoi cell points. They will grow in size and then recede.
             If during ray marching, a Voronoi seed is not found before the limit (VORONOI_BACKGROUND) a more realistic Voronoi diagram(background) is shown behind the moving spheres.   

** NOTE: look for the smoothing of the 3 objects with the spheres and traces...

*/



const float MIN_DIST = 0.0;
const int MAX_STEPS = 100;
const float MAX_DIST = 100.0;   
const float PRECISION = 0.01; 
const float TIME_INTERVAL = 10.0;       // the time in seconds between switching scenes
const float VORONOI_BACKGROUND = -8.0;  // In the 'Z' where the voronoi background starts
const float RAYMARCH_TRACE_THICKNESS = 0.1;
const float VORONOI_SPHERE_SPEED = 0.05;



//******************************************
//** material for all objects on the screen
//******************************************
struct Material {
  vec3 ambientColor; // k_a * i_a
  vec3 diffuseColor; // k_d * i_d
  vec3 specularColor; // k_s * i_s
  float alpha; // shininess
};


//**********************
//** Individual objects
//**********************
struct sObject
{
    float sd;       // distance 
    Material mat;
};



//******************
//** Object colors
//******************
Material gold() {
  vec3 aCol = 0.5 * vec3(0.7, 0.5, 0);
  vec3 dCol = 0.6 * vec3(0.7, 0.7, 0);
  vec3 sCol = 0.6 * vec3(1, 1, 1);
  float a = 5.;

  return Material(aCol, dCol, sCol, a);
}

Material blue() {
  vec3 aCol = 0.5 * vec3(0.0, 0.3, 0.5);
  vec3 dCol = 0.6 * vec3(0.0, 0.7, 0.7);
  vec3 sCol = 0.6 * vec3(1, 1, 1);
  float a = 5.;

  return Material(aCol, dCol, sCol, a);
}

Material red() {
  vec3 aCol = 0.5 * vec3(0.7, 0.3, 0.0);
  vec3 dCol = 0.6 * vec3(0.0, 0.7, 0.7);
  vec3 sCol = 0.6 * vec3(1, 1, 1);
  float a = 5.;

  return Material(aCol, dCol, sCol, a);
}

Material voronoiCell() {
  vec3 aCol = 0.5 * vec3(0.0, 0.3, 0.0);
  vec3 dCol = 0.6 * vec3(0.0, 0.7, 0.7);
  vec3 sCol = 0.6 * vec3(1, 1, 1);
  float a = 5.;

  return Material(aCol, dCol, sCol, a);
}



//**********************
//** None smooth union
//**********************
sObject opUnion(sObject obj1, sObject obj2) 
{
  if (obj2.sd < obj1.sd) return obj2;
  return obj1;
}



//**************************
//** Smooth union + helper
//**************************

// Cubic Polynomial Smooth-minimum
vec2 smin( float a, float b, float k )
{
    k *= 6.0;
    float h = max( k-abs(a-b), 0.0 )/k;
    float m = h*h*h*0.5;
    float s = m*k*(1.0/3.0); 
    return (a<b) ? vec2(a-s,m) : vec2(b-s,1.0-m);
}

sObject opSmoothUnion(sObject obj1, sObject obj2, float k) 
{
    // get sd values in .x and materials blending in .y
    vec2 m = smin(obj1.sd, obj2.sd, k);

    float sd = m.x;   

    float a = m.y;
    vec3 ambient = mix(obj1.mat.ambientColor, obj2.mat.ambientColor, a);
    vec3 diffuse = mix(obj1.mat.diffuseColor, obj2.mat.diffuseColor, a);
    vec3 specular = mix(obj1.mat.specularColor, obj2.mat.specularColor, a);
    float alpha = mix(obj1.mat.alpha, obj2.mat.alpha, a);

    return (sObject(sd, Material(ambient, diffuse, specular, alpha)));
}



//************************
//** Random functions
//************************
float rand(vec2 p){
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 random3( vec3 p ) 
{
    return fract(sin(vec3(dot(p,vec3(127.1,311.7,232.1)),dot(p,vec3(269.5,183.3,123.4)),dot(p,vec3(127.1,311.7,223.5))))*43758.5453);
}


//*************************************
//** Rotation matrix around the X axis.
//*************************************
mat3 rotateX(float theta)
{
    float c = cos(theta);
    float s = sin(theta);
    return mat3(vec3(1, 0, 0),
                vec3(0, c, -s),
                vec3(0, s, c)
    );
}



//***********
//** Objects
//***********

float sdSphere(vec3 p, float r )
{
   return (length(p) - r) + rand(p.xy * 10.0) * 0.001;  // add some noise to the sphere
}


float sdTorus( vec3 p, vec2 t )
{
  p = p * rotateX(1.7);
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}


//*****************************************************************
// sdVoronoi()
// showTrace: display the trace of the ray march
// voronoiZ: 'Z' value of where to display the voronoi background
//*****************************************************************
float sdVoronoi(vec3 p, bool showTrace, float voronoiZ)
{
    float speed = 0.5;

    if (showTrace == true)
    {
        p.z = 0.0;      // by setting the z to a fixed value, the ray march leaves a visible path
        speed = 1.5;
    }
    else
    {
        // This is the distance to draw the voronoi background
        if (p.z <= voronoiZ)
        {
           return(-1.);   
        }
    }

    vec3 i_st = floor(p); 
    vec3 f_st = fract(p);

    float m_dist = 1.5;  // minimum distance

    for (int z = -1; z <= 1; z++)
    {
        for (int y= -1; y <= 1; y++) 
        {
            for (int x= -1; x <= 1; x++) 
            {
                // Neighbor place in the grid
                vec3 neighbor = vec3(float(x),float(y), float((showTrace == false) ? float(z) : 0.0));  

                // Random position from current + neighbor place in the grid
                vec3 pt = random3(i_st + neighbor);

			    // Animate the point
                pt = 0.5 + 0.5*sin(iTime * speed + 6.*pt);  //here

			    // vector between the pixel and the point
                vec3 diff = neighbor + pt - f_st;

                // Distance to the point
                float dist = length(diff);

                // Keep the closer distance
                m_dist = min(m_dist, dist);
            }
        }
   }

   // give the found cells a greater width that varies        
   return(m_dist - abs(sin(iTime * VORONOI_SPHERE_SPEED)) * RAYMARCH_TRACE_THICKNESS);  
}




//***********************************
//** place all objects in the screen 
//***********************************
sObject scene(vec3 p)
{
    // determines what scene choice is currently running
    bool voronoiChoice = (mod(floor(iTime / TIME_INTERVAL), 2.0) == 0.0) ? false : true;

    sObject dVol     = sObject(sdVoronoi(p, voronoiChoice, VORONOI_BACKGROUND), voronoiCell());
    sObject dSphere1 = sObject(sdSphere(p - vec3(2.8, 0.0, 0.0), 1.), gold());
    sObject dSphere2 = sObject(sdSphere(p - vec3(-2.4, -1.0, 0.0), 0.5), blue());
    sObject dTorus   = sObject(sdTorus(p - vec3(-1.0, 1.5, 0.0), vec2(0.6, 0.2)), red());

    return (opSmoothUnion(dVol, opUnion(dSphere1,opUnion(dSphere2,dTorus)),0.05));          
}



//*************
//** RAY MARCH
//*************
sObject raymarch(vec3 ro, vec3 rd) 
{
  float depth = MIN_DIST;
  sObject co;

  vec3 color = vec3(0.0);

  for(int i = 0; i < MAX_STEPS; i++) 
  {
    vec3 p = ro + rd * depth;

    co = scene(p);
    depth += co.sd;

    if(co.sd < PRECISION || depth > MAX_DIST)  {
        break;
    }
  }

  co.sd = depth;
  return co;
}



//***********
//** camera
//***********
mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
	vec3 cd = normalize(lookAtPoint - cameraPos); // camera direction
	vec3 cr = normalize(cross(vec3(0, 1, 0), cd)); // camera right
	vec3 cu = normalize(cross(cd, cr)); // camera up

	return mat3(-cr, cu, -cd);
}


//***************************
//** For light calculations
//***************************
vec3 calcNormal(vec3 p) 
{
    vec2 e = vec2(1.0, -1.0) * 0.0005;

    return normalize(e.xyy * scene(p + e.xyy).sd +
                     e.yyx * scene(p + e.yyx).sd +
                     e.yxy * scene(p + e.yxy).sd +
                     e.xxx * scene(p + e.xxx).sd);
}



vec3 phong(vec3 lightDir, vec3 normal, vec3 rd, Material mat)
{
  // ambient
  vec3 ambient = mat.ambientColor;

  // diffuse
  float dotLN = clamp(dot(lightDir, normal), 0., 1.);
  vec3 diffuse = mat.diffuseColor * dotLN;

  // specular
  float dotRV = clamp(dot(reflect(lightDir, normal), -rd), 0., 1.);
  vec3 specular = mat.specularColor * pow(dotRV, mat.alpha);

  return ambient + diffuse + specular;
}



//*********
//** MAIN
//*********
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

  vec2 uv = fragCoord.xy/iResolution.xy;
  uv -= 0.5;
  uv.x *= iResolution.x / iResolution.y;

  // Light Position
  vec3 lightPosition = vec3(-10.0 * cos(iTime), 10.0, 10.0 * sin(iTime));

  vec3 lp = vec3(0.0,0.0,0.0); // lookat point (aka camera target)
  vec3 ro = vec3(0.3, 0.0, 5.0); // I set the ray origin to be slightly off center as the ray would occasionally black out the screen;
  vec3 rd = camera(ro, lp) * normalize(vec3(uv, -1)); // ray direction  

  vec3 col = vec3(0.0);

  sObject co = raymarch(ro, rd); // get closest object

  vec3 p = ro + rd * co.sd;

  fragColor = vec4(0.0);  // default color


  if (co.sd <= 4.0) // This is to give the floating spheres and traces a slight color variation depending on depth
  {
      co.mat.ambientColor = clamp(  mix(co.mat.ambientColor, vec3(0., 0.2, 0.1), co.sd),vec3(0.0),vec3(1.0));
  }         

  vec3 normal = calcNormal(p);

  // light #1
  vec3 lightPosition1 = vec3(-8, -6, -5);
  vec3 lightDirection1 = normalize(lightPosition1 - p);
  float lightIntensity1 = 0.9;

  // light #2
  vec3 lightPosition2 = vec3(1, 1, 1);
  vec3 lightDirection2 = normalize(lightPosition2 - p);

  //float lightIntensity2 = 0.5; //0.5;
  vec3 lightIntensity2 = vec3(0.1,0.1,0.8);

  // final color of object
  col = lightIntensity1 * phong(lightDirection1, normal, rd, co.mat);
  col += lightIntensity2 * phong(lightDirection2, normal , rd, co.mat); 

  fragColor = vec4(col, 1.0);
}
